[assembly: SuppressMessage("Reliability", "G3E0002", Scope = "member", Target = "~M:g3.TriangleBoxTree.#ctor(System.Collections.Generic.List{g3.AxisAlignedBox3d})", Justification = "reviewed: leaf boxes written per index")]
