// ExactMeshEdgeGroups (the assembly's and the classification's edge groups): every parallel loop goes through ForBlocks, which runs
// fixed blocks of an index range, each block written by one task only (its own slots of an output array, or its own entries of a
// per-block array). The callers listed here are the members that pass a body: GroupEdges (keys and items per triangle), the
// blocked radix sort (a histogram per block, then the scatter of each block to its own offsets, so equal keys keep their order), the
// union-find (compare-and-swap on int slots, the larger root under the smaller, so the classes and their roots do not depend on
// the order of the unions), NumberClasses (roots counted and numbered per block, the others read the number of their root) and
// UsedPoints (marks of one value). Integers only; no floating-point value is written, read across tasks or reduced
[assembly: SuppressMessage("Reliability", "G3E0002", Scope = "member", Target = "~M:g3.ExactMeshEdgeGroups.ForBlocks(System.Int32,System.Action{System.Int32})", Justification = "reviewed: fixed blocks of an index range, one writer per block, integer arrays (and doubles copied unchanged); the analyzer flags only this member, so each caller listed above was reviewed here and a new caller needs a review (docs/REVIEW_CHECKLIST.md section 9)")]
[assembly: SuppressMessage("Reliability", "G3E0002", Scope = "member", Target = "~M:g3.ExactMeshEdgeGroups.SortByKeyParallel(System.Int64[],System.Int32[],System.Int32,System.Int64)", Justification = "reviewed: integer keys; a stable partition into key ranges (blocks write their own offsets), then each range sorted on its own by the serial stable radix sort into its own slots; the unique stable order, whatever the schedule")]
[assembly: SuppressMessage("Reliability", "G3E0002", Scope = "member", Target = "~M:g3.ExactMeshResultBuilder.TryBuild(System.Collections.Generic.List{g3.Index3i},System.Int32[],System.Collections.Generic.List{System.Int32},g3.Vector3d[],System.Int32[],System.Int64[],System.Int32[])~g3.DMesh3", Justification = "reviewed: blocks of the sorted edges, of the slots, of the edges and of the vertices through ExactMeshEdgeGroups.ForBlocks, each block writing its own entries of integer arrays (the edge numbers by a prefix sum over the blocks) and the vertex positions copied unchanged (no arithmetic on them); the mesh is built by DMesh3.FromEdgeStructure with the ids that AppendVertex and AppendTriangle give")]
[assembly: SuppressMessage("Reliability", "G3E0002", Scope = "member", Target = "~M:g3.ExactMeshBoolean.join_slots(System.Collections.Generic.List{g3.Index3i},System.Int32[],System.Int64[],System.Int32[],System.Collections.Generic.List{System.Collections.Generic.KeyValuePair{System.Int64,System.Collections.Generic.List{System.Collections.Generic.KeyValuePair{System.Int32,System.Int32}}}})", Justification = "reviewed: the groups of two pieces by blocks of the sorted edges, unions of int slots (order-independent forest), conflicts counted per block and summed serially; the larger groups serially afterwards in the order of the sorted edges")]

[assembly: SuppressMessage("Reliability", "G3E0002", Scope = "member", Target = "~M:g3.ExactMeshBoolean.join_pieces(System.Collections.Generic.List{g3.ExactMeshArrangement.OutputTriangle},System.Collections.Generic.List{System.Int32}[],System.Int64[],System.Int32[],System.Int32[],System.Collections.Generic.List{System.Int64})", Justification = "reviewed: the groups of equal edges by blocks of the sorted edges (read-only stacks and constraint set), unions of int pieces (order-independent forest), the joins of the L1 list per block and appended in block order; no floating-point value")]

